#include <stdio.h>
#include <string.h>



int main(void) {
    char s[3][101];
    scanf("%100s%100s%100s", s[0], s[1], s[2]);
    int best = 0;
    for (int i = 1; i < 3; i++) if (strcmp(s[i], s[best]) > 0) best = i;
    puts(s[best]);
    return 0;
}
